COMMIT;

-- Check SDO metadata - will be created upon spatial index creation
SELECT * FROM USER_SDO_GEOM_METADATA WHERE table_name = 'TRAM_LINES';

-- Create spatial index for line geometries
-- (CBTREE is only available for point data, so a regular R-tree based SPATIAL_INDEX_V2 is used)
CREATE INDEX IF NOT EXISTS tram_lines_sidx
ON tram_lines (geom)
INDEXTYPE IS MDSYS.SPATIAL_INDEX_V2 PARAMETERS ('layer_gtype=LINE');

-- If needed, drop the index
-- DROP INDEX tram_lines_sidx FORCE;

-- Re-check SDO metadata after spatial index creation
SELECT * FROM USER_SDO_GEOM_METADATA WHERE table_name = 'TRAM_LINES';

-- Show the data, filtered with the predefined SDO_GTYPE and SDO_SRID constants
SELECT
  l.route_variant_id,
  l.line_ref,
  l.route_name,
  l.from_stop,
  l.to_stop,
  SDO_UTIL.GETNUMVERTICES(l.geom) AS num_vertices,
  ROUND(SDO_GEOM.SDO_LENGTH(l.geom, 0.05, 'unit=KM'), 2) AS length_km,
  SDO_GEOM.VALIDATE_GEOMETRY_WITH_CONTEXT(l.geom, 0.05) AS validation
FROM
  tram_lines l
WHERE
  l.geom.sdo_gtype = SDO_LINESTRING2D
  AND l.geom.sdo_srid = SDO_LONLAT
ORDER BY
  l.route_variant_id;

-- Cross-check with TRAM_STATIONS (./insert_tram_stations.sql):
-- each directional stop position should lie on the track of its direction (distance ~0 m)
SELECT
  l.route_name,
  s.station_code,
  s.station_name,
  ROUND(
    SDO_GEOM.SDO_DISTANCE(
      CASE l.to_stop WHEN 'Sopot' THEN s.geom_to_sopot ELSE s.geom_to_crnomerec END,
      l.geom, 0.05, 'unit=M'),
    1) AS distance_to_track_m
FROM
  tram_lines l
  JOIN tram_stations s ON s.tram_line = l.line_ref
ORDER BY
  l.route_name,
  s.station_code;
